import subprocess
cmd=['cargo','test','--locked','--offline','--manifest-path','native/Cargo.toml','-p','inir-mega','sync_read::tests']
try:
    p=subprocess.run(cmd,cwd='.',capture_output=True,text=True,timeout=160)
except subprocess.TimeoutExpired:
    raise SystemExit(25)
blob=(p.stdout or '')+'\n'+(p.stderr or '')
low=blob.lower()
if p.returncode == 0: raise SystemExit(0)
fg=('feature_gates.rs' in blob)
arity=("can't compare" in low or 'cannot compare' in low or 'no implementation' in low or 'partialeq' in low or 'e0277' in low)
if fg and arity: raise SystemExit(21)
if fg and '--output-cols=ID,RUN_STATE,STATUS' in blob: raise SystemExit(22)
if 'could not compile' in low or 'error[e' in low or '\nerror:' in low: raise SystemExit(23)
raise SystemExit(24)
